+#!/usr/bin/perl
+use strict;
+use warnings;
+use File::Find;
+use File::Basename;
+
+my $repo = '/bench/repo';
+my $module = 'github.com/usememos/memos';
+
+# decls: key -> { name, file, line, pkg, import_path, kind, recv }
+my %decls;
+# pkg_name -> import_path for internal packages (may have duplicates across dirs)
+my %pkg_to_paths;
+# import_path -> default local name
+my %path_local;
+
+sub read_file {
+    my ($path) = @_;
+    open my $fh, '<', $path or return '';
+    local $/;
+    my $content = <$fh>;
+    close $fh;
+    return $content // '';
+}
+
+sub local_name_for_import {
+    my ($imp) = @_;
+    if ($imp =~ /^\s*(\w+)\s+"(.+)"\s*$/) {
+        return ($2, $1);
+    }
+    if ($imp =~ /^\s*"(.+)"\s*$/) {
+        my $p = $1;
+        my $local = $p;
+        $local =~ s{.*/}{};
+        return ($p, $local);
+    }
+    return;
+}
+
+sub parse_imports {
+    my ($content) = @_;
+    my %imports; # local -> path
+    while ($content =~ /import\s+(?:\(\s*([\s\S]*?)\s*\)|(\S+)\s+"([^"]+)")/g) {
+        my $block = $1 // '';
+        if ($2) {
+            my ($local, $path) = ($2, $3);
+            $imports{$local} = $path;
+            next;
+        }
+        for my $line (split /\n/, $block) {
+            $line =~ s|//.*||;
+            next unless $line =~ /"/;
+            my ($path, $local) = local_name_for_import($line);
+            next unless defined $path;
+            $imports{$local} = $path;
+        }
+    }
+    return %imports;
+}
+
+# Collect declarations under internal/
+find({
+    wanted => sub {
+        return unless /\.go$/;
+        return unless $File::Find::name =~ m|^$repo/internal/|;
+        my $file = $File::Find::name;
+        my $content = read_file($file);
+        my ($pkg) = $content =~ /^package\s+(\w+)/m;
+        return unless defined $pkg;
+
+        # derive import path from file location
+        my $rel = $file;
+        $rel =~ s|^\Q$repo/\E||;
+        $rel =~ s|/[^/]+$||;
+        my $import_path = "$module/$rel";
+        push @{ $pkg_to_paths{$pkg} }, $import_path unless grep { $_ eq $import_path } @{ $pkg_to_paths{$pkg} // [] };
+        $path_local{$import_path} = $pkg;
+
+        my $line_num = 0;
+        for my $line (split /\n/, $content) {
+            $line_num++;
+            if ($line =~ /^func\s+\(([^)]*)\)\s+(\w+)\s*\(/) {
+                my ($recv, $name) = ($1, $2);
+                next if $name eq 'init';
+                my $key = "$import_path::$name";
+                $decls{$key} = {
+                    name => $name,
+                    file => $file,
+                    line => $line_num,
+                    pkg => $pkg,
+                    import_path => $import_path,
+                    kind => 'method',
+                    recv => $recv,
+                };
+            } elsif ($line =~ /^func\s+(\w+)\s*\(/) {
+                my $name = $1;
+                next if $name eq 'init';
+                my $key = "$import_path::$name";
+                $decls{$key} = {
+                    name => $name,
+                    file => $file,
+                    line => $line_num,
+                    pkg => $pkg,
+                    import_path => $import_path,
+                    kind => 'func',
+                };
+            }
+        }
+    },
+    no_chdir => 1,
+}, "$repo/internal");
+
+# Count call sites repo-wide
+my %fanin;
+
+find({
+    wanted => sub {
+        return unless /\.go$/;
+        my $file = $File::Find::name;
+        my $content = read_file($file);
+        my ($file_pkg) = $content =~ /^package\s+(\w+)/m;
+        my %imports = parse_imports($content);
+
+        # Build reverse: import_path -> [local names]
+        my %path_locals;
+        for my $local (keys %imports) {
+            push @{ $path_locals{ $imports{$local} } }, $local;
+        }
+
+        # Same-package internal decls for this file
+        my $rel = $file;
+        $rel =~ s|^\Q$repo/\E||;
+        $rel =~ s|/[^/]+$||;
+        my $file_import_path = ($rel eq '') ? $module : "$module/$rel";
+
+        for my $key (keys %decls) {
+            my $d = $decls{$key};
+            my $name = $d->{name};
+            my $count = 0;
+
+            if ($d->{kind} eq 'func') {
+                # qualified: local.name(
+                for my $local (@{ $path_locals{ $d->{import_path} } // [] }) {
+                    my $pat = qr/\b\Q$local\E\.\Q$name\E\s*\(/;
+                    $count += () = ($content =~ /$pat/g);
+                }
+                # unqualified in same package
+                if (defined $file_pkg && $file_pkg eq $d->{pkg} && $file =~ m|^$repo/internal/|) {
+                    # same directory package only
+                    my $decl_dir = $d->{file};
+                    $decl_dir =~ s|/[^/]+$||;
+                    my $file_dir = $file;
+                    $file_dir =~ s|/[^/]+$||;
+                    if ($decl_dir eq $file_dir) {
+                        my $pat = qr/(?<![.\w])\Q$name\E\s*\(/;
+                        for my $line (split /\n/, $content) {
+                            next if $line =~ /^func\s+(\w+\s*)?\Q$name\E\s*\(/;
+                            next if $line =~ /^func\s+\([^)]*\)\s+\Q$name\E\s*\(/;
+                            $count++ while $line =~ /$pat/g;
+                        }
+                    }
+                }
+            } else {
+                # method: .name(
+                my $pat = qr/\.\Q$name\E\s*\(/;
+                for my $line (split /\n/, $content) {
+                    next if $line =~ /^func\s+\([^)]*\)\s+\Q$name\E\s*\(/;
+                    $count++ while $line =~ /$pat/g;
+                }
+            }
+            $fanin{$key} = $count;
+        }
+    },
+    no_chdir => 1,
+}, $repo);
+
+# Sort and print top results
+my @sorted = sort { $fanin{$b} <=> $fanin{$a} || $a cmp $b } keys %decls;
+
+print "TOP 30 by fan-in:\n";
+for my $i (0..29) {
+    last unless defined $sorted[$i];
+    my $k = $sorted[$i];
+    my $d = $decls{$k};
+    my $sym = ($d->{kind} eq 'method') ? "(*).$d->{name}" : $d->{name};
+    print sprintf("%4d  %s  %s:%d  [%s]\n", $fanin{$k}, $sym, $d->{file}, $d->{line}, $d->{kind});
+}
+
+my $top = $sorted[0];
+my $d = $decls{$top};
+print "\nWINNER: $d->{name} — $d->{file} — $fanin{$top}\n";

