+#!/usr/bin/perl
+use strict;
+use warnings;
+
+my $repo = '/bench/repo';
+my $module = 'github.com/usememos/memos';
+
+my %decls;
+my %fanin;
+
+sub read_file {
+    my ($path) = @_;
+    open my $fh, '<', $path or return '';
+    local $/;
+    my $content = <$fh>;
+    close $fh;
+    return $content // '';
+}
+
+sub file_dir {
+    my ($file) = @_;
+    (my $d = $file) =~ s|/[^/]+$||;
+    return $d;
+}
+
+sub local_name_for_import {
+    my ($imp) = @_;
+    if ($imp =~ /^\s*(\w+)\s+"(.+)"\s*$/) { return ($2, $1); }
+    if ($imp =~ /^\s*"(.+)"\s*$/) {
+        my $p = $1; my $local = $p; $local =~ s{.*/}{}; return ($p, $local);
+    }
+    return;
+}
+
+sub parse_imports {
+    my ($content) = @_;
+    my %imports;
+    while ($content =~ /import\s+(?:\(\s*([\s\S]*?)\s*\)|(\S+)\s+"([^"]+)")/g) {
+        my $block = $1 // '';
+        if ($2) { $imports{$2} = $3; next; }
+        for my $line (split /\n/, $block) {
+            $line =~ s|//.*||;
+            next unless $line =~ /"/;
+            my ($path, $local) = local_name_for_import($line);
+            next unless defined $path;
+            $imports{$local} = $path;
+        }
+    }
+    return %imports;
+}
+
+sub import_path_for_file {
+    my ($file) = @_;
+    my $rel = $file; $rel =~ s|^\Q$repo/\E||; $rel =~ s|/[^/]+$||;
+    return ($rel eq '') ? $module : "$module/$rel";
+}
+
+sub collect_decls {
+    my ($file) = @_;
+    return unless $file =~ m|^$repo/internal/.*\.go$|;
+    my $content = read_file($file);
+    my ($pkg) = $content =~ /^package\s+(\w+)/m;
+    return unless defined $pkg;
+    my $import_path = import_path_for_file($file);
+    my $dir = file_dir($file);
+    my $line_num = 0;
+    for my $line (split /\n/, $content) {
+        $line_num++;
+        if ($line =~ /^func\s+\(([^)]*)\)\s+(\w+)\s*\(/) {
+            my ($recv, $name) = ($1, $2);
+            next if $name eq 'init';
+            my $recv_type = '';
+            if ($recv =~ /(\*?\s*[\w\.]+)\s*$/) { $recv_type = $1; $recv_type =~ s/\s+//g; }
+            my $key = "${import_path}::${name}::method::${recv_type}";
+            $decls{$key} = { name => $name, file => $file, line => $line_num, pkg => $pkg,
+                import_path => $import_path, kind => 'method', recv_type => $recv_type, dir => $dir };
+        } elsif ($line =~ /^func\s+(\w+)\s*\(/) {
+            my $name = $1; next if $name eq 'init';
+            my $key = "${import_path}::${name}::func";
+            $decls{$key} = { name => $name, file => $file, line => $line_num, pkg => $pkg,
+                import_path => $import_path, kind => 'func', dir => $dir };
+        }
+    }
+}
+
+sub is_decl_line {
+    my ($line, $name) = @_;
+    return 1 if $line =~ /^func\s+(\w+\s*)?\Q$name\E\s*\(/;
+    return 1 if $line =~ /^func\s+\([^)]*\)\s+\Q$name\E\s*\(/;
+    return 0;
+}
+
+sub count_calls_in_file {
+    my ($file) = @_;
+    return unless $file =~ /\.go$/;
+    my $content = read_file($file);
+    my ($file_pkg) = $content =~ /^package\s+(\w+)/m;
+    my %imports = parse_imports($content);
+    my %path_locals;
+    for my $local (keys %imports) { push @{ $path_locals{ $imports{$local} } }, $local; }
+    my $file_dir = file_dir($file);
+
+    for my $key (keys %decls) {
+        my $d = $decls{$key};
+        my $name = $d->{name};
+        my $count = 0;
+
+        if ($d->{kind} eq 'func') {
+            for my $local (@{ $path_locals{ $d->{import_path} } // [] }) {
+                my $pat = qr/\b\Q$local\E\.\Q$name\E\s*\(/;
+                $count += () = ($content =~ /$pat/g);
+            }
+            if (defined $file_pkg && $file_pkg eq $d->{pkg} && $file_dir eq $d->{dir}) {
+                my $pat = qr/(?<![.\w])\Q$name\E\s*\(/;
+                for my $line (split /\n/, $content) {
+                    next if is_decl_line($line, $name);
+                    $count++ while $line =~ /$pat/g;
+                }
+            }
+        } else {
+            # Methods: skip names that collide with widespread stdlib/interface methods
+            next if $name =~ /^(Error|String|Len|Less|Swap|Kind|Next|Field|Info|Stop|Start|Register|Validate|Format|Parse|Compile)$/;
+            my $pat = qr/\.\Q$name\E\s*\(/;
+            for my $line (split /\n/, $content) {
+                next if is_decl_line($line, $name);
+                $count++ while $line =~ /$pat/g;
+            }
+        }
+        $fanin{$key} += $count;
+    }
+}
+
+open my $find, '-|', 'find', $repo, '-name', '*.go', '-type', 'f', '-print' or die $!;
+while (my $file = <$find>) { chomp $file; collect_decls($file); }
+close $find;
+
+open $find, '-|', 'find', $repo, '-name', '*.go', '-type', 'f', '-print' or die $!;
+while (my $file = <$find>) { chomp $file; count_calls_in_file($file); }
+close $find;
+
+my @sorted = sort { $fanin{$b} <=> $fanin{$a} || $a cmp $b } keys %decls;
+print "TOP 25 (functions + non-generic methods):\n";
+for my $i (0..24) {
+    last unless defined $sorted[$i];
+    my $k = $sorted[$i]; my $d = $decls{$k};
+    print sprintf("%4d  %s  %s:%d  [%s %s]\n", $fanin{$k}, $d->{name}, $d->{file}, $d->{line}, $d->{kind}, $d->{recv_type}//'');
+}
+my $top = $sorted[0]; my $d = $decls{$top};
+print "\nWINNER: $d->{name} — $d->{file} — $fanin{$top}\n";

