+#!/usr/bin/perl
+use strict;
+use warnings;
+
+my $repo = '/bench/repo';
+my $module = 'github.com/usememos/memos';
+my (%decls, %fanin);
+
+sub read_file { my ($p)=@_; open my $f,'<',$p or return ''; local $/; my $c=<$f>; close $f; $c//'' }
+sub file_dir { my ($f)=@_; (my $d=$f)=~s|/[^/]+$||; $d }
+
+sub parse_imports {
+  my ($c)=@_; my %imp;
+  while ($c =~ /import\s+(?:\(\s*([\s\S]*?)\s*\)|(\S+)\s+"([^"]+)")/g) {
+    my ($blk,$a,$p)=($1,$2,$3);
+    if ($a) { $imp{$a}=$p; next }
+    for (split /\n/,$blk) { s|//.*||; next unless /"/;
+      if (/^\s*(\w+)\s+"(.+)"/) { $imp{$1}=$2 }
+      elsif (/^\s*"(.+)"/) { my $x=$1; (my $l=$x)=~s{.*/}{}; $imp{$l}=$x }
+    }
+  }
+  %imp
+}
+
+sub import_path { my ($f)=@_; my $r=$f; $r=~s|^\Q$repo/\E||; $r=~s|/[^/]+$||; $r eq '' ? $module : "$module/$r" }
+sub is_decl { my ($l,$n)=@_; $l=~/^func\s+(\w+\s*)?\Q$n\E\s*\(/ || $l=~/^func\s+\([^)]*\)\s+\Q$n\E\s*\(/ }
+
+open my $find,'-|','find',$repo,'-name','*.go','-type','f' or die $!;
+while (<$find>) {
+  chomp; my $file=$_; next unless $file=~/^$repo\/internal\//;
+  my $content=read_file($file); my ($pkg)=$content=~/^package\s+(\w+)/m; next unless $pkg;
+  my $ip=import_path($file); my $dir=file_dir($file); my $ln=0;
+  for (split /\n/,$content) {
+    $ln++;
+    if (/^func\s+\(([^)]*)\)\s+(\w+)\s*\(/) {
+      next if $2 eq 'init';
+      my ($recv,$name)=($1,$2); my $rt=''; if ($recv=~/(\*?\s*[\w\.]+)\s*$/) { $rt=$1; $rt=~s/\s+//g }
+      my $k="${ip}::${name}::method::${rt}";
+      $decls{$k}={name=>$name,file=>$file,line=>$ln,kind=>'method',ip=>$ip,pkg=>$pkg,dir=>$dir,recv=>$rt};
+    } elsif (/^func\s+(\w+)\s*\(/) {
+      next if $1 eq 'init';
+      my $k="${ip}::$1::func";
+      $decls{$k}={name=>$1,file=>$file,line=>$ln,kind=>'func',ip=>$ip,pkg=>$pkg,dir=>$dir};
+    }
+  }
+}
+close $find;
+
+open $find,'-|','find',$repo,'-name','*.go','-type','f' or die $!;
+while (<$find>) {
+  chomp; my $file=$_; my $content=read_file($file);
+  my ($fpkg)=$content=~/^package\s+(\w+)/m; my %imp=parse_imports($content);
+  my %pl; for (keys %imp) { push @{$pl{$imp{$_}}}, $_ }
+  my $fdir=file_dir($file);
+  for my $k (keys %decls) {
+    my $d=$decls{$k}; my $n=$d->{name}; my $c=0;
+    if ($d->{kind} eq 'func') {
+      for (@{$pl{$d->{ip}} // []}) { my $pat=qr/\b\Q$_\E\.\Q$n\E\s*\(/; $c+=()=($content=~/$pat/g) }
+      if (defined $fpkg && $fpkg eq $d->{pkg} && $fdir eq $d->{dir}) {
+        my $pat=qr/(?<![.\w])\Q$n\E\s*\(/;
+        for (split /\n/,$content) { next if is_decl($_,$n); $c+=()=/$pat/g }
+      }
+    } else {
+      my $pat=qr/\.\Q$n\E\s*\(/;
+      for (split /\n/,$content) { next if is_decl($_,$n); $c+=()=/$pat/g }
+    }
+    $fanin{$k}+=$c;
+  }
+}
+close $find;
+
+my @sorted=sort { ($fanin{$b}//0) <=> ($fanin{$a}//0) || $a cmp $b } keys %decls;
+print "TOP 30 ALL (including generic methods):\n";
+for my $i (0..29) {
+  my $k=$sorted[$i]; my $d=$decls{$k};
+  printf "%4d  %s  %s:%d  [%s]\n", ($fanin{$k}//0), $d->{name}, $d->{file}, $d->{line}, $d->{kind};
+}

